        }
        chatInput {
            background: transparent; border: none; outline: none; resize: none; color: white;
            fontsize: 0.9rem; flexgrow: 1; padding: 8px 10px; maxheight: 120px;
        }
        sendBtn {
            width: 38px; height: 38px; borderradius: 50%;
            background: lineargradient(135deg, 667eea, 764ba2);
            color: white; flexshrink: 0; display: flex; alignitems: center; justifycontent: center;
            transition: all 0.3s ease; transform: scale(0.9); opacity: 0.5;
        }
        sendBtn:not(:disabled) { transform: scale(1); opacity: 1; }
        sendBtn i { transition: transform 0.2s ease; }
        sendBtn:not(:disabled):active i { transform: scale(0.9) rotate(10deg); }

        / 3D Avatár konténer /
        .aiiconcontainer {
            width: 40px; height: 40px; flexshrink: 0; position: relative;
        }
        .aiiconcanvas { width: 100% !important; height: 100% !important; }

        / Képgenerálás stílusok /
        .generatedimage { maxwidth: 100%; borderradius: 12px; margintop: 8px; }
        .loader {
            width: 18px; height: 18px; border: 2px solid rgba(255,255,255,0.3);
            borderleftcolor: fff; borderradius: 50%; display: inlineblock;
            animation: spin 1s linear infinite; marginright: 8px;
        }
        @keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
