    <div class="container">
        <header>
            <h1>Képalkotó</h1>
            <p class="subtitle">Személyre szabott képek készítése</p>
        </header>

        <div class="infobanner">
            <svg class="infoicon" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokelinecap="round" strokelinejoin="round" strokewidth="2" d="M13 16h1v4h1m14h.01M21 12a9 9 0 1118 0 9 9 0 0118 0z"></path>
            </svg>
            <span>Az adataid nem kerülnek tárolásra, csak a kép elkészítéséhez használjuk fel őket.</span>
        </div>

        <div class="maingrid">
            <div class="inputsection">
                <div class="inputgroup">
                    <label for="appearance">Megjelenés</label>
                    <textarea 
                        id="appearance" 
                        placeholder="Írd le a külsődet (hajszín, szemszín, testalkat, ruházat...)"
                    ></textarea>
                    <span class="helpertext">Minél részletesebb, annál pontosabb lesz az eredmény</span>
                </div>

                <div class="inputgroup">
                    <label for="scene">Jelenet</label>
                    <textarea 
                        id="scene" 
                        placeholder="Hol és mit csinálsz a képen? (környezet, tevékenység, hangulat...)"
                    ></textarea>
                    <span class="helpertext">Például: Kávézóban ülök és könyvet olvasok</span>
                </div>

                <button id="generateBtn" class="button">
                    <span>Kép készítése</span>
                </button>
            </div>

            <div class="outputsection">
                <div id="placeholder" class="outputplaceholder">
                    <svg fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokelinecap="round" strokelinejoin="round" strokewidth="1.5" d="M4 16l4.5864.586a2 2 0 012.828 0L16 16m22l1.5861.586a2 2 0 012.828 0L20 14m66h.01M6 20h12a2 2 0 0022V6a2 2 0 0022H6a2 2 0 002 2v12a2 2 0 002 2z"></path>
                    </svg>
                    <p>A generált kép itt fog megjelenni</p>
                </div>

                <div id="loading" class="loading" style="display: none;">
                    <div class="spinner"></div>
                    <span>Kép készítése folyamatban...</span>
                </div>

                <img id="result" class="generatedimage" style="display: none;" alt="Generált kép">
            </div>
        </div>
    </div>

    <div id="error" class="errormessage"></div>

    <script>
        const appearanceInput = document.getElementById('appearance');
        const sceneInput = document.getElementById('scene');
        const generateBtn = document.getElementById('generateBtn');
        const placeholder = document.getElementById('placeholder');
        const loading = document.getElementById('loading');
        const resultImg = document.getElementById('result');
        const errorEl = document.getElementById('error');

        function showError(message) {
            errorEl.textContent = message;
            errorEl.classList.add('show');
            setTimeout(() => errorEl.classList.remove('show'), 5000);
        }

        generateBtn.addEventListener('click', async () => {
            const appearance = appearanceInput.value.trim();
            const scene = sceneInput.value.trim();

            if (!appearance || !scene) {
                showError('Kérlek töltsd ki mindkét mezőt');
                return;
            }

            // UI state
            placeholder.style.display = 'none';
            resultImg.style.display = 'none';
            loading.style.display = 'flex';
            generateBtn.disabled = true;
            generateBtn.textContent = 'Feldolgozás...';

            try {
                const prompt = ${appearance}, ${scene}, high quality, natural lighting, photorealistic;

                const response = await fetch('', {
                    method: 'POST',
                    headers: { 'ContentType': 'application/json' },
                    body: JSON.stringify({
                        instances: [{ prompt }],
                        parameters: { 
                            sampleCount: 1,
                            aspectRatio: "1:1"
                        }
                    })
                });

                const data = await response.json();

                if (data.predictions?.[0]?.bytesBase64Encoded) {
                    resultImg.src = data:image/png;base64,${data.predictions[0].bytesBase64Encoded};
                    resultImg.style.display = 'block';
                } else {
                    throw new Error('Nem sikerült képet generálni');
                }
            } catch (error) {
                showError('Hiba történt. Próbáld újra később.');
                placeholder.style.display = 'flex';
            } finally {
                loading.style.display = 'none';
                generateBtn.disabled = false;
                generateBtn.textContent = 'Kép készítése';
            }
        });
    </script>
</body>
</html>


