    <style>
        /* ... (a meglévő stílusok változatlanul maradnak) ... */
        /* Lásd az előző példában */
        .image-modal-bg {
            position: fixed; inset: 0; background: rgba(0,0,0,0.5); z-index: 1000; display: flex; align-items: center; justify-content: center;
