        }
        .image-modal label { font-weight: 500; margin-bottom: 4px; display: block; }
        .image-modal textarea {
            width: 100%; border-radius: 10px; border: 1px solid #444; background: #18181b; color: #fff; padding: 10px 12px; margin-bottom: 12px; resize: vertical; min-height: 60px; font-size: 0.95rem;
        }
        .image-modal .error { color: #ef4444; font-size: 0.9em; margin-bottom: 8px; }
        .image-modal .modal-actions { display: flex; gap: 12px; margin-top: 8px; }
        .image-modal button {
            border-radius: 8px; padding: 10px 18px; font-weight: 500; font-size: 1rem; border: none; cursor: pointer;
        }
        .image-modal .generate-btn { background: linear-gradient(90deg,#667eea,#764ba2); color: #fff; }
        .image-modal .cancel-btn { background: #232323; color: #fff; }
    </style>
</head>
<body class="text-white min-h-screen flex flex-col overflow-hidden">
    <!-- ... (sidebar, header, chatView, stb. változatlanul) ... -->

    <main class="flex-1 flex flex-col h-screen">
        <header class="p-4 border-b border-white/10 bg-[rgba(0,0,0,0.2)] flex-shrink-0 glass-effect">
            <div class="flex items-center justify-between">
                <div class="flex items-center gap-3">
                    <button id="openSidebar" class="w-10 h-10 rounded-full flex items-center justify-center btn-interactive">
                        <i class="fas fa-bars text-sm"></i>
                    </button>
                    <div class="ai-icon-container"><canvas class="ai-icon-canvas"></canvas></div>
                    <h2 class="text-base font-semibold">JADE</h2>
                </div>
            </div>
        </header>

        <section id="chatView" class="flex-1 overflow-y-auto scrollbar-thin p-4 space-y-6">
            <!-- ... (kezdő üzenet, javaslat gombok, stb.) ... -->
            <div class="flex gap-3 chat-bubble">
                <div class="ai-icon-container"><canvas class="ai-icon-canvas"></canvas></div>
                <div class="flex-1 max-w-[85%]">
                    <div class="bg-[rgba(0,0,0,0.4)] rounded-2xl rounded-tl-md p-4 glass-effect">
                        <p class="text-sm leading-relaxed">Szia! Készen állok, hogy segítsek. Próbáld ki a képgenerálást is! Kattints a <b>Kép generálása</b> gombra lent, és add meg a részleteket.</p>
                    </div>
