                    <span class="text-sm font-medium">Kép generálása</span>
                </button>
                <button class="bg-[rgba(0,0,0,0.2)] rounded-xl p-4 text-left glass-effect suggestion-btn">
                    <i class="fas fa-code text-blue-400 mb-2 block text-lg"></i>
                    <span class="text-sm font-medium">Kód segítség</span>
