    <!-- Képgeneráló modális ablak -->
    <div id="imageModal" class="image-modal-bg" style="display:none;">
        <div class="image-modal">
            <h3 class="text-lg font-semibold mb-2">Kép generálása</h3>
            <label for="appearance">Megjelenés</label>
            <textarea id="appearance" placeholder="Írd le a külsődet (hajszín, szemszín, testalkat, ruházat...)"></textarea>
            <label for="scene">Jelenet</label>
            <textarea id="scene" placeholder="Hol és mit csinálsz a képen? (környezet, tevékenység, hangulat...)"></textarea>
            <div id="imageModalError" class="error" style="display:none;"></div>
